DROP TABLE IF EXISTS sys_permission;
CREATE TABLE sys_permission (
    `id` BIGINT NOT NULL COMMENT '主键ID',
    `parent_id` VARCHAR(64),
    `code` VARCHAR(200),
    `name` VARCHAR(200),
    `can_favorite` int,
    `menu_alias` VARCHAR(200),
    `bus_params` VARCHAR(1024),
    `bus_group` VARCHAR(64),
    `url` VARCHAR(510),
    `component` VARCHAR(510),
    `component_name` VARCHAR(200),
    `redirect` VARCHAR(510),
    `menu_type` int,
    `perms` VARCHAR(510),
    `perms_type` VARCHAR(20),
    `sort_no` DECIMAL(8,2) NOT NULL,
    `always_show` int,
    `icon` VARCHAR(200),
    `is_route` int,
    `is_leaf` int,
    `keep_alive` int,
    `hidden` int,
    `description` VARCHAR(510),
    `create_by` VARCHAR(64),
    `create_time` datetime,
    `update_by` VARCHAR(64),
    `update_time` datetime,
    `del_flag` int NOT NULL,
    `rule_flag` int,
    `status` VARCHAR(4) NOT NULL,
    `internal_or_external` int,
    `system_type` VARCHAR(128),
    `hidden_type` bit(1) NOT NULL,
    PRIMARY KEY (id)
) COMMENT = '按钮菜单表';

